```python
class KnowledgeSearch:
    def __init__(self, notion_client, database_id):
        self.notion = notion_client
        self.database_id = database_id

    def search_notes(self, query, category=None, tags=None):
        """
        搜索笔记

        参数:
            query: 搜索关键词
            category: 筛选类别
            tags: 筛选标签
        """

        # 构建 Notion 查询
        filter_params = {
            "property": "Title",
            "title": {
                "contains": query
            }
        }

        # 添加类别筛选
        if category:
            filter_params = {
                "and": [
                    filter_params,
                    {
                        "property": "Category",
                        "select": {
                            "equals": category
                        }
                    }
                ]
            }

        # 添加标签筛选
        if tags:
            tag_filters = [
                {
                    "property": "Tags",
                    "multi_select": {
                        "contains": tag
                    }
                }
                for tag in tags
            ]

            if 'and' in filter_params:
                filter_params['and'].extend(tag_filters)
            else:
                filter_params = {
                    "and": [filter_params] + tag_filters
                }

        # 执行查询
        try:
            results = self.notion.databases.query(
                database_id=self.database_id,
                filter=filter_params
            )

            notes = []
            for page in results['results']:
                note = self._parse_note(page)
                if note:
                    notes.append(note)

            return notes

        except Exception as e:
            print(f"搜索失败: {e}")
            return []

    def _parse_note(self, page):
        """解析笔记信息"""
        try:
            title = page['properties']['Title']['title'][0]['text']['content']

            category = page['properties']['Category']['select']
            category = category['name'] if category else 'General'

            tags = [tag['name'] for tag in page['properties']['Tags']['multi_select']]

            return {
                'id': page['id'],
                'title': title,
                'category': category,
                'tags': tags,
                'url': page['url']
            }

        except Exception as e:
            print(f"解析笔记失败: {e}")
            return None

    def get_recent_notes(self, days=7, limit=10):
        """获取最近的笔记"""
        from datetime import datetime, timedelta

        cutoff_date = datetime.now() - timedelta(days=days)

        try:
            results = self.notion.databases.query(
                database_id=self.database_id,
                filter={
                    "property": "Created",
                    "date": {
                        "after": cutoff_date.isoformat()
                    }
                },
                sort=[
                    {
                        "property": "Created",
                        "direction": "descending"
                    }
                ],
                page_size=limit
            )

            notes = []
            for page in results['results']:
                note = self._parse_note(page)
                if note:
                    notes.append(note)

            return notes

        except Exception as e:
            print(f"获取最近笔记失败: {e}")
            return []

# 使用示例
if __name__ == "__main__":
    note_taker = QuickNote()
    search = KnowledgeSearch(note_taker.notion, note_taker.database_id)

    # 搜索笔记
    results = search.search_notes(
        query='Python',
        category='技术',
        tags=['Python', '编程']
    )

    print(f"找到 {len(results)} 条笔记：")
    for note in results:
        print(f"- {note['title']} ({note['category']})")
        print(f"  标签: {', '.join(note['tags'])}")
        print(f"  链接: {note['url']}")
