## 实战案例：边缘函数链

```javascript
// 中间件模式
class MiddlewareChain {
  constructor() {
    this.middlewares = [];
  }

  use(middleware) {
    this.middlewares.push(middleware);
    return this;
  }

  async handle(request, env, ctx) {
    let index = 0;

    const next = async () => {
      if (index < this.middlewares.length) {
        const middleware = this.middlewares[index++];
        return middleware(request, env, ctx, next);
      }
    };

    return next();
  }
}

// 中间件示例
const corsMiddleware = (request, env, ctx, next) => {
  const response = await next();
  response.headers.set('Access-Control-Allow-Origin', '*');
  return response;
};

const authMiddleware = async (request, env, ctx, next) => {
  const token = request.headers.get('Authorization');
  const isValid = await validateToken(token, env);

  if (!isValid) {
    return new Response('Unauthorized', { status: 401 });
  }

  return next();
};

const cacheMiddleware = async (request, env, ctx, next) => {
  const cacheKey = new Request(request.url, request);
  const cache = caches.default;

  const cached = await cache.match(cacheKey);
  if (cached) {
    return cached;
  }

  const response = await next();
  ctx.waitUntil(cache.put(cacheKey, response.clone()));
  return response;
};

// 使用中间件
export default {
  async fetch(request, env, ctx) {
    const chain = new MiddlewareChain()
      .use(corsMiddleware)
      .use(authMiddleware)
      .use(cacheMiddleware);

    return chain.handle(request, env, ctx, () => {
      return Response.json({ message: 'Hello!' });
    });
  }
};
```

