class ComplianceManager:
    def __init__(self):
        self.retention_periods = {
            'audit_logs': 2555,  # 7 年（天）
            'user_data': 1825,    # 5 年
            'transaction_logs': 3650  # 10 年
        }

    def check_retention(self, data_type: str, 
                       created_at: datetime) -> bool:
        """检查数据保留期限"""
        if data_type not in self.retention_periods:
            return True

        days_old = (datetime.utcnow() - created_at).days
        return days_old < self.retention_periods[data_type]

    def ensure_gdpr_compliance(self, user_data: dict):
        """确保 GDPR 合规"""
        required = [
            'consent_timestamp',
            'data_purpose',
            'retention_period'
        ]

        missing = [r for r in required if r not in user_data]
        if missing:
            raise ValueError(
                f"Missing required GDPR fields: {missing}"
            )

    def anonymize_user_data(self, user_data: dict) -> dict:
        """用户数据匿名化（GDPR 被遗忘权）"""
        anonymized = {
            'user_id': hash(user_data['user_id']),
            'email': '***@***.***',
            'name': 'Anonymous',
            'anonymized_at': datetime.utcnow().isoformat()
        }
