```javascript
const { GraphQLUpload } = require('graphql-upload');

const typeDefs = `
  scalar Upload

  type Mutation {
    uploadFile(file: Upload!): String!
  }
`;

const resolvers = {
  Upload: GraphQLUpload,
  Mutation: {
