### Node.js 生产者

```javascript
const amqp = require('amqplib');

async function sendEmail(to, subject, body) {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  const queue = 'email_queue';
  const exchange = 'email_exchange';

  // 声明交换机和队列
  await channel.assertExchange(exchange, 'direct', { durable: true });
  await channel.assertQueue(queue, { durable: true });
  await channel.bindQueue(queue, exchange, 'email');

  // 发送消息
  const message = {
    to,
    subject,
    body,
    timestamp: new Date().toISOString()
  };

  channel.publish(exchange, 'email', Buffer.from(JSON.stringify(message)), {
    persistent: true,  // 消息持久化
    contentType: 'application/json'
  });

  console.log('Email sent:', message);

  await channel.close();
  await connection.close();
}

// 使用
sendEmail('user@example.com', 'Welcome', 'Thank you for registering!');
```

### Node.js 消费者

```javascript
const amqp = require('amqplib');

async function consumeEmails() {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  const queue = 'email_queue';

  // 设置 prefetch，控制未确认消息数量
  await channel.prefetch(1);

  await channel.assertQueue(queue, { durable: true });

  console.log('Waiting for emails...');

  channel.consume(queue, async (msg) => {
    if (msg) {
      try {
        const content = JSON.parse(msg.content.toString());
        console.log('Processing email:', content);

        // 模拟发送邮件
        await sendEmail(content.to, content.subject, content.body);

        // 确认消息
        channel.ack(msg);
        console.log('Email processed successfully');
      } catch (error) {
        console.error('Error processing email:', error);

        // 拒绝消息并重新入队
        channel.nack(msg, false, true);
      }
    }
  }, {
    noAck: false  // 手动确认
  });
}

function sendEmail(to, subject, body) {
  return new Promise((resolve) => {
    console.log(`Sending email to ${to}...`);
    setTimeout(() => {
      console.log(`Email sent to ${to}`);
      resolve();
    }, 1000);
  });
}

consumeEmails().catch(console.error);
```

### 死信队列

```javascript
async function setupDeadLetterQueue() {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  // 死信交换机和队列
  const dlx = 'email_dlx';
  const dlq = 'email_dlq';

  await channel.assertExchange(dlx, 'direct', { durable: true });
  await channel.assertQueue(dlq, { durable: true });
  await channel.bindQueue(dlq, dlx, 'email');

  // 主队列配置
  await channel.assertQueue('email_queue', {
    durable: true,
    arguments: {
      'x-dead-letter-exchange': dlx,
      'x-dead-letter-routing-key': 'email',
      'x-max-retries': 3
    }
  });

  // 消费死信队列
  channel.consume(dlq, (msg) => {
    console.error('Dead letter message:', msg.content.toString());
    // 记录到数据库或发送告警
    channel.ack(msg);
  });
}
```

