### 库存服务（消费者）

```javascript
const { Kafka } = require('kafkajs');

const kafka = new Kafka({ brokers: ['localhost:9092'] });
const consumer = kafka.consumer({ groupId: 'inventory-service' });

async function consumeOrders() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'orders' });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const event = JSON.parse(message.value.toString());

      if (event.eventType === 'OrderCreated') {
        const order = event.data;
        console.log('Reserving inventory for order:', order.id);

        try {
          // 扣减库存
          for (const item of order.items) {
            await db.inventory.update(
              { productId: item.productId },
              { $inc: { quantity: -item.quantity } }
            );
          }

          console.log('Inventory reserved for order:', order.id);
        } catch (error) {
          console.error('Failed to reserve inventory:', error);
          // 可以发送失败事件或重试
        }
      }
    }
  });
}

consumeOrders().catch(console.error);
```

### 支付服务（消费者）

```javascript
const kafka = new Kafka({ brokers: ['localhost:9092'] });
const producer = kafka.producer();
const consumer = kafka.consumer({ groupId: 'payment-service' });

async function consumeOrders() {
  await producer.connect();
  await consumer.connect();
  await consumer.subscribe({ topic: 'orders' });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const event = JSON.parse(message.value.toString());

      if (event.eventType === 'OrderCreated') {
        const order = event.data;

        try {
          // 处理支付
          const payment = await processPayment(order);

          // 发布支付成功事件
          await producer.send({
            topic: 'payments',
            messages: [{
              key: order.id,
              value: JSON.stringify({
                eventType: 'PaymentSucceeded',
                timestamp: Date.now(),
                data: { orderId: order.id, payment }
              })
            }]
          });
        } catch (error) {
          // 发布支付失败事件
          await producer.send({
            topic: 'payments',
            messages: [{
              key: order.id,
              value: JSON.stringify({
                eventType: 'PaymentFailed',
                timestamp: Date.now(),
                data: { orderId: order.id, error: error.message }
              })
            }]
          });
        }
      }
    }
  });
}

function processPayment(order) {
  return {
    id: `PAY-${Date.now()}`,
    orderId: order.id,
    amount: order.total,
    status: 'completed'
  };
}
```

