## CRDT（无冲突复制数据类型）

### G-Counter（增长计数器）

```javascript
class GCounter {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.counts = new Map(); // nodeId -> count
    this.counts.set(nodeId, 0);
  }

  increment() {
    const current = this.counts.get(this.nodeId) || 0;
    this.counts.set(this.nodeId, current + 1);
  }

  value() {
    return Array.from(this.counts.values()).reduce((a, b) => a + b, 0);
  }

  merge(other) {
    for (const [node, count] of other.counts) {
      const current = this.counts.get(node) || 0;
      this.counts.set(node, Math.max(current, count));
    }
  }

  serialize() {
    return JSON.stringify(Object.fromEntries(this.counts));
  }

  static deserialize(data, nodeId) {
    const counter = new GCounter(nodeId);
    counter.counts = new Map(Object.entries(JSON.parse(data)));
    return counter;
  }
}

// 使用
const counter1 = new GCounter('node-1');
const counter2 = new GCounter('node-2');

counter1.increment();
counter1.increment();
counter2.increment();

console.log(counter1.value()); // 2
console.log(counter2.value()); // 1

// 合并
counter1.merge(counter2);
console.log(counter1.value()); // 3
```

### LWW-Register（最后写胜出寄存器）

```javascript
class LWWRegister {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.value = null;
    this.timestamp = 0;
  }

  set(value) {
    this.timestamp = Date.now();
    this.value = value;
  }

  merge(other) {
    if (other.timestamp > this.timestamp ||
        (other.timestamp === this.timestamp && other.nodeId > this.nodeId)) {
      this.value = other.value;
      this.timestamp = other.timestamp;
    }
  }
}
```

### OR-Set（Observed-Remove Set）

```javascript
class ORSet {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.elements = new Map(); // element -> Set of unique tags
  }

  add(element) {
    const tag = `${this.nodeId}-${Date.now()}-${Math.random()}`;

    if (!this.elements.has(element)) {
      this.elements.set(element, new Set());
    }

    this.elements.get(element).add(tag);
  }

  remove(element) {
    this.elements.delete(element);
  }

  has(element) {
    return this.elements.has(element);
  }

  elements() {
    return Array.from(this.elements.keys());
  }

  merge(other) {
    for (const [element, otherTags] of other.elements) {
      const myTags = this.elements.get(element) || new Set();

      // 合并 tags
      for (const tag of otherTags) {
        myTags.add(tag);
      }

      this.elements.set(element, myTags);
    }
  }
}
```

## 操作转换（OT）

### 基础操作转换

```javascript
class OperationTransformer {
  // 转换插入操作
  static transformInsert(op1, op2) {
    const { index: index1 } = op1;
    const { index: index2, text } = op2;

    if (index2 <= index1) {
      return { ...op1, index: index1 + text.length };
    }

    return op1;
  }

  // 转换删除操作
  static transformDelete(op1, op2) {
    const { index: index1, length } = op1;
    const { index: index2, length: length2 } = op2;

    if (index2 + length2 <= index1) {
      // op2 在 op1 之前
      return { ...op1, index: index1 - length2 };
    } else if (index2 >= index1 + length) {
      // op2 在 op1 之后
      return op1;
    } else {
      // 重叠
      const overlapStart = Math.max(index1, index2);
      const overlapEnd = Math.min(index1 + length, index2 + length2);
      const overlapLength = overlapEnd - overlapStart;

      return {
        ...op1,
        length: length - overlapLength,
        index: index1
      };
    }
  }

  // 转换两个操作
  static transform(op1, op2) {
    if (op1.type === 'insert' && op2.type === 'insert') {
      return this.transformInsert(op1, op2);
    } else if (op1.type === 'delete' && op2.type === 'delete') {
      return this.transformDelete(op1, op2);
    } else if (op1.type === 'insert' && op2.type === 'delete') {
      const { index: index1 } = op1;
      const { index: index2, length } = op2;

      if (index2 < index1) {
        return { ...op1, index: index1 - length };
      }
      return op1;
    }

    return op1;
  }
}
```

### 协作编辑器

```javascript
class CollaborativeEditor {
  constructor() {
    this.content = '';
    this.revision = 0;
    this.pendingOps = [];
  }

  apply(op) {
    const { type, index, text, length, revision } = op;

    // 转换操作
    const transformedOp = this.pendingOps.reduce(
      (acc, pending) => OperationTransformer.transform(acc, pending),
      op
    );

    // 应用操作
    if (type === 'insert') {
      this.content =
        this.content.slice(0, transformedOp.index) +
        text +
        this.content.slice(transformedOp.index);
    } else if (type === 'delete') {
      this.content =
        this.content.slice(0, transformedOp.index) +
        this.content.slice(transformedOp.index + transformedOp.length);
    }

    this.revision++;
    this.pendingOps = this.pendingOps.filter(p => p.revision !== revision);

    return {
      content: this.content,
      revision: this.revision
    };
  }

  insert(index, text) {
    const op = {
      type: 'insert',
      index,
      text,
      revision: ++this.revision
    };

    return this.apply(op);
  }

  delete(index, length) {
    const op = {
      type: 'delete',
      index,
      length,
      revision: ++this.revision
    };

    return this.apply(op);
  }
}
```

## 离线优先架构

### 本地状态管理

```javascript
class OfflineFirstStore {
  constructor() {
    this.localState = this.loadState();
    this.pendingOps = this.loadPendingOps();
  }

  loadState() {
    const data = localStorage.getItem('state');
    return data ? JSON.parse(data) : {};
  }

  saveState() {
    localStorage.setItem('state', JSON.stringify(this.localState));
  }

  loadPendingOps() {
    const data = localStorage.getItem('pending_ops');
    return data ? JSON.parse(data) : [];
  }

  savePendingOps() {
    localStorage.setItem('pending_ops', JSON.stringify(this.pendingOps));
  }

  apply(op) {
    // 应用到本地状态
    this.localState = this.applyOperation(this.localState, op);
    this.saveState();

    // 添加到待同步队列
    this.pendingOps.push({
      ...op,
      id: this.generateId(),
      timestamp: Date.now()
    });
    this.savePendingOps();

    // 尝试同步
    this.sync();
  }

  async sync() {
    if (!navigator.onLine || this.pendingOps.length === 0) {
      return;
    }

    try {
      const response = await fetch('/api/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ops: this.pendingOps })
      });

      if (response.ok) {
        const { applied } = await response.json();

        // 移除已同步的操作
        this.pendingOps = this.pendingOps.filter(
          op => !applied.includes(op.id)
        );
        this.savePendingOps();
      }
    } catch (error) {
      console.error('Sync failed:', error);
      // 操作保留在队列中，下次重试
    }
  }

  applyOperation(state, op) {
    // 实现操作应用逻辑
    return state;
  }

  generateId() {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}
```

