## 实战案例：实时协作编辑器

### 服务器

```javascript
const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: 3000 });

const documents = new Map();
const clients = new Map();

wss.on('connection', (ws) => {
  ws.on('message', (data) => {
    const message = JSON.parse(data);

    switch (message.type) {
      case 'join':
        handleJoin(ws, message);
        break;
      case 'op':
        handleOperation(ws, message);
        break;
    }
  });
});

function handleJoin(ws, { documentId, userId }) {
  // 初始化文档
  if (!documents.has(documentId)) {
    documents.set(documentId, {
      content: '',
      revision: 0,
      users: new Set()
    });
  }

  const doc = documents.get(documentId);
  doc.users.add(userId);
  clients.set(userId, ws);

  // 发送当前文档状态
  ws.send(JSON.stringify({
    type: 'init',
    content: doc.content,
    revision: doc.revision
  }));

  // 通知其他用户
  broadcast(documentId, {
    type: 'user_joined',
    userId
  }, userId);
}

function handleOperation(ws, { documentId, userId, op }) {
  const doc = documents.get(documentId);

  // 应用操作
  doc.content = applyOp(doc.content, op);
  doc.revision++;

  // 广播给其他用户
  broadcast(documentId, {
    type: 'op',
    op,
    revision: doc.revision,
    userId
  }, userId);
}

function broadcast(documentId, message, excludeUserId) {
  const doc = documents.get(documentId);

  doc.users.forEach((userId) => {
    if (userId !== excludeUserId) {
      const client = clients.get(userId);
      if (client?.readyState === WebSocket.OPEN) {
        client.send(JSON.stringify(message));
      }
    }
  });
}
```

## 常见问题 (FAQ)

### Q: WebSocket 和 SSE 如何选择？

A: 
- **WebSocket**: 双向通信、实时游戏、协作编辑
- **SSE**: 服务器推送、实时通知、简单场景

### Q: 如何处理冲突？

A: 
1. CRDT：无冲突自动合并
2. OT：操作转换
3. Last-Write-Wins：最后写入胜出
4. 应用层冲突解决

### Q: 如何保证离线数据一致性？

A: 
1. 本地存储所有操作
2. 操作带时间戳和唯一 ID
3. 重连后按顺序同步
4. 使用 CRDT 避免冲突

