### 2. Shell 应用架构

```javascript
// Shell App - 主应用框架
import React, { useEffect, useState } from 'react';

const MicroFrontends = {
  products: {
    url: 'http://localhost:3001',
    route: '/products'
  },
  cart: {
    url: 'http://localhost:3002',
    route: '/cart'
  },
  checkout: {
    url: 'http://localhost:3003',
    route: '/checkout'
  }
};

function ShellApp() {
  const [activeApp, setActiveApp] = useState(null);
  const [currentRoute, setCurrentRoute] = useState('/');

  useEffect(() => {
    const handleRouteChange = () => {
      const path = window.location.pathname;
      setCurrentRoute(path);

      // 根据路径激活对应的微前端
      const app = Object.values(MicroFrontends).find(
        app => path.startsWith(app.route)
      );

      if (app && activeApp !== app.url) {
        loadMicroFrontend(app);
      }
    };

    window.addEventListener('popstate', handleRouteChange);
    handleRouteChange();

    return () => window.removeEventListener('popstate', handleRouteChange);
  }, [activeApp]);

  const loadMicroFrontend = async (app) => {
    setActiveApp(app.url);

    // 动态加载远程脚本
    const script = document.createElement('script');
    script.src = `${app.url}/remoteEntry.js`;
    script.type = 'text/javascript';
    script.async = true;

    script.onload = () => {
      console.log(`Loaded ${app.url}`);
    };

    document.head.appendChild(script);
  };

  return (
    <div className="shell-app">
      <header>
        <nav>
          <button onClick={() => window.history.pushState({}, '', '/products')}>
            Products
          </button>
          <button onClick={() => window.history.pushState({}, '', '/cart')}>
            Cart
          </button>
          <button onClick={() => window.history.pushState({}, '', '/checkout')}>
            Checkout
          </button>
        </nav>
      </header>

      <main id="micro-frontend-root">
        {/* 微前端将渲染在这里 */}
      </main>
    </div>
  );
}

export default ShellApp;
```

### 3. 应用间状态共享

```javascript
// 共享状态管理 - Event Bus
import { useEffect, useState } from 'react';

// 创建事件总线
class EventBus {
  constructor() {
    this.events = {};
  }

  on(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  off(event, callback) {
    if (this.events[event]) {
      this.events[event] = this.events[event].filter(cb => cb !== callback);
    }
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

// 创建全局事件总线
const eventBus = new EventBus();

// 跨应用状态 Hook
function useSharedState(key, initialValue) {
  const [state, setState] = useState(() => {
    // 从 sessionStorage 获取初始值
    const saved = sessionStorage.getItem(key);
    return saved ? JSON.parse(saved) : initialValue;
  });

  useEffect(() => {
    // 监听状态变化
    const handleStateChange = (newState) => {
      setState(newState);
    };

    eventBus.on(`${key}_change`, handleStateChange);

    return () => {
      eventBus.off(`${key}_change`, handleStateChange);
    };
  }, [key]);

  const setSharedState = (newState) => {
    setState(newState);
    sessionStorage.setItem(key, JSON.stringify(newState));
    eventBus.emit(`${key}_change`, newState);
  };

  return [state, setSharedState];
}

// 使用示例 - Cart App
function CartApp() {
  const [cartItems, setCartItems] = useSharedState('cart_items', []);

  const addToCart = (product) => {
    setCartItems([...cartItems, product]);
  };

  return (
    <div>
      <h2>Shopping Cart</h2>
      <ul>
        {cartItems.map((item, index) => (
          <li key={index}>{item.name}</li>
        ))}
      </ul>
    </div>
  );
}
```

