#### Shadow DOM 封装

```javascript
// Shadow DOM Wrapper
import React, { useEffect, useRef } from 'react';

function ShadowDOMWrapper({ children }) {
  const containerRef = useRef(null);
  const shadowRootRef = useRef(null);

  useEffect(() => {
    if (containerRef.current && !shadowRootRef.current) {
      // 创建 Shadow DOM
      shadowRootRef.current = containerRef.current.attachShadow({ mode: 'open' });

      // 创建样式容器
      const style = document.createElement('style');
      style.textContent = `
        :host {
          display: block;
          all: initial;
        }
        * {
          box-sizing: border-box;
        }
      `;

      shadowRootRef.current.appendChild(style);

      // 创建内容容器
      const content = document.createElement('div');
      content.className = 'shadow-content';
      shadowRootRef.current.appendChild(content);
    }
  }, []);

  useEffect(() => {
    if (shadowRootRef.current) {
      const content = shadowRootRef.current.querySelector('.shadow-content');

      // 渲染子组件到 Shadow DOM
      import('react-dom').then(({ createRoot }) => {
        const root = createRoot(content);
        root.render(children);
      });
    }
  }, [children]);

  return <div ref={containerRef} />;
}

// 使用示例
function App() {
  return (
    <ShadowDOMWrapper>
      <CartApp />
    </ShadowDOMWrapper>
  );
}
```

### 5. 版本管理和回滚

```javascript
// 版本管理配置
const MicroFrontendVersions = {
  products: {
    current: 'v1.2.0',
    available: ['v1.0.0', 'v1.1.0', 'v1.2.0', 'v1.3.0-beta']
  },
  cart: {
    current: 'v2.1.0',
    available: ['v2.0.0', 'v2.1.0']
  },
  checkout: {
    current: 'v1.0.5',
    available: ['v1.0.0', 'v1.0.5']
  }
};

// 版本切换功能
function switchMicroFrontendVersion(appName, version) {
  const app = MicroFrontendVersions[appName];

  if (!app || !app.available.includes(version)) {
    console.error(`Invalid version: ${version}`);
    return;
  }

  // 卸载当前版本
  const script = document.querySelector(
    `script[data-app="${appName}"]`
  );

  if (script) {
    script.remove();
  }

  // 加载新版本
  const newScript = document.createElement('script');
  newScript.src = `http://localhost:3001/${version}/remoteEntry.js`;
  newScript.dataset.app = appName;
  newScript.onload = () => {
    console.log(`Switched ${appName} to ${version}`);
    // 重新渲染应用
    window.location.reload();
  };

  document.head.appendChild(newScript);
  app.current = version;
}

// A/B 测试支持
function getABTestVariant(appName, userId) {
  const hash = hashCode(userId);
  const variant = hash % 2;

  return variant === 0 ? 'current' : 'new';
}

function loadMicroFrontendWithABTest(appName, userId) {
  const app = MicroFrontendVersions[appName];
  const variant = getABTestVariant(appName, userId);

  const version = variant === 'current'
    ? app.current
    : app.available[app.available.length - 1]; // 最新版本

  loadMicroFrontend({
    ...app,
    version
  });
}

function hashCode(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return hash;
}
```

### 6. 性能监控

```javascript
// 性能监控工具
class MicroFrontendMonitor {
  constructor() {
    this.metrics = new Map();
    this.observers = [];
  }

  // 监控加载时间
  observeLoadTime(appName) {
    const startTime = performance.now();

    return {
      end: () => {
        const loadTime = performance.now() - startTime;
        this.recordMetric(appName, 'loadTime', loadTime);
      }
    };
  }

  // 监控运行时错误
  observeErrors(appName) {
    const errorHandler = (event) => {
      this.recordMetric(appName, 'error', {
        message: event.message,
        stack: event.error?.stack,
        timestamp: Date.now()
      });
    };

    window.addEventListener('error', errorHandler);

    return () => {
      window.removeEventListener('error', errorHandler);
    };
  }

  // 记录指标
  recordMetric(appName, metricName, value) {
    if (!this.metrics.has(appName)) {
      this.metrics.set(appName, {});
    }

    const appMetrics = this.metrics.get(appName);

    if (!appMetrics[metricName]) {
      appMetrics[metricName] = [];
    }

    appMetrics[metricName].push(value);

    // 通知观察者
    this.observers.forEach(observer => {
      observer({
        appName,
        metricName,
        value
      });
    });
  }

  // 订阅指标
  subscribe(callback) {
    this.observers.push(callback);

    return () => {
      this.observers = this.observers.filter(obs => obs !== callback);
    };
  }

  // 获取报告
  getReport(appName) {
    const appMetrics = this.metrics.get(appName) || {};

    const report = {};

    for (const [metricName, values] of Object.entries(appMetrics)) {
      if (metricName === 'error') {
        report[metricName] = {
          count: values.length,
          errors: values
        };
      } else {
        const avg = values.reduce((a, b) => a + b, 0) / values.length;
        const max = Math.max(...values);
        const min = Math.min(...values);

        report[metricName] = { avg, max, min };
      }
    }

    return report;
  }
}

// 使用示例
const monitor = new MicroFrontendMonitor();

// 监控加载时间
function loadMicroFrontendWithMonitor(app) {
  const observer = monitor.observeLoadTime(app.name);

  loadMicroFrontend(app).then(() => {
    observer.end();
  });
}

// 订阅指标变化
monitor.subscribe(({ appName, metricName, value }) => {
  console.log(`[${appName}] ${metricName}:`, value);

  // 发送到监控系统
  sendToMonitoring({
    app: appName,
    metric: metricName,
    value
  });
});
```

