#### Write-Through Pattern

```javascript
async function updateProduct(productId, updates) {
  const cacheKey = `product:${productId}`;

  // 1. 同时更新数据库和缓存
  const [updatedProduct] = await Promise.all([
    db.products.update(
      { id: productId },
      { $set: updates }
    ),
    redis.setex(
      cacheKey,
      3600,
      JSON.stringify({ ...updates, id: productId })
    )
  ]);

  return updatedProduct;
}
```

#### Write-Behind Pattern

```javascript
const writeQueue = [];
let writeTimer = null;

async function updateProductAsync(productId, updates) {
  // 1. 立即更新缓存
  const cacheKey = `product:${productId}`;
  await redis.setex(
    cacheKey,
    3600,
    JSON.stringify({ ...updates, id: productId })
  );

  // 2. 加入写队列
  writeQueue.push({ productId, updates });

  // 3. 批量写入数据库
  if (!writeTimer) {
    writeTimer = setTimeout(async () => {
      const batch = writeQueue.splice(0);

      await db.products.bulkWrite(
        batch.map(item => ({
          updateOne: {
            filter: { id: item.productId },
            update: { $set: item.updates }
          }
        }))
      );

      writeTimer = null;
    }, 100); // 100ms 批量写入
  }
}
```

