```javascript
const NULL_CACHE_PREFIX = 'null:';

async function getProductWithProtection(productId) {
  const cacheKey = `product:${productId}`;

  // 检查缓存
  let product = await redis.get(cacheKey);

  if (product) {
    if (product.startsWith(NULL_CACHE_PREFIX)) {
      // 空对象缓存，防止穿透
      return null;
    }
    return JSON.parse(product);
  }

  // 从数据库获取
  product = await db.products.findOne({ id: productId });

  if (product) {
    await redis.setex(
      cacheKey,
      3600,
      JSON.stringify(product)
    );
  } else {
    // 缓存空对象，设置较短过期时间
    await redis.setex(
      cacheKey,
      300, // 5 分钟
      NULL_CACHE_PREFIX + 'null'
    );
  }

  return product;
}
