# AI Agent 工作流自动化

AI Agent 是能够自主感知、推理和行动的智能系统。本教程将深入讲解如何设计和实现复杂的 AI Agent 工作流，构建强大的自动化系统。

## Agent 设计模式

### ReAct 模式

ReAct（Reasoning + Acting）是最基础的 Agent 模式。

```javascript
class ReActAgent {
  constructor(llm, tools) {
    this.llm = llm;
    this.tools = tools;
    this.maxIterations = 10;
  }

  async run(query) {
    let iterations = 0;
    let thought = query;
    const history = [];

    while (iterations < this.maxIterations) {
      iterations++;

      // 1. 推理下一步行动
      const prompt = this.buildPrompt(thought, history);
      const response = await this.llm.complete(prompt);

      // 2. 解析响应
      const { action, actionInput, observation } = this.parseResponse(response);

      if (action === 'finish') {
        return observation;
      }

      // 3. 执行工具
      const result = await this.executeTool(action, actionInput);

      // 4. 记录观察
      thought = `Observation: ${result}`;
      history.push({ action, actionInput, result });
    }

    throw new Error('Max iterations exceeded');
  }

  buildPrompt(thought, history) {
    return `
Thought: ${thought}

Available tools: ${Object.keys(this.tools).join(', ')}

${history.map(h => `Action: ${h.action}\nInput: ${h.actionInput}\nObservation: ${h.result}`).join('\n\n')}

What should I do next? (respond with Action: tool_name, Input: input)
`;
  }

  parseResponse(response) {
    const actionMatch = response.match(/Action: (\w+)/);
    const inputMatch = response.match(/Input: (.+)/);

    const action = actionMatch ? actionMatch[1] : null;
    const actionInput = inputMatch ? inputMatch[1].trim() : null;

    if (action === 'finish') {
      return {
        action: 'finish',
        observation: response.match(/Observation: (.+)/)?.[1]
      };
    }

    return { action, actionInput };
  }

  async executeTool(action, input) {
    const tool = this.tools[action];

    if (!tool) {
      return `Error: Tool ${action} not found`;
    }

    try {
      return await tool.run(JSON.parse(input));
    } catch (error) {
      return `Error: ${error.message}`;
    }
  }
}
```

### 计划执行模式

```javascript
class PlanningAgent {
  constructor(llm, tools) {
    this.llm = llm;
    this.tools = tools;
  }

  async run(goal) {
    // 1. 生成计划
    const plan = await this.createPlan(goal);
    console.log('Plan:', plan);

    // 2. 执行计划
    const results = [];
    for (const step of plan.steps) {
      console.log(`Executing step: ${step.description}`);

      const result = await this.executeStep(step);
      results.push({
        step: step.description,
        result
      });

      // 3. 评估是否需要调整计划
      if (result.needsReplanning) {
        const updatedPlan = await this.updatePlan(plan, results);
        plan.steps = updatedPlan.steps;
      }
    }

    return results;
  }

  async createPlan(goal) {
    const prompt = `
Goal: ${goal}

Available tools:
${Object.keys(this.tools).map(name => `- ${name}: ${this.tools[name].description}`).join('\n')}

Create a step-by-step plan to achieve the goal.

Format your response as JSON:
{
  "steps": [
    {
      "step": 1,
      "description": "Step description",
      "tool": "tool_name",
      "input": "tool input"
    }
  ]
}
`;

    const response = await this.llm.complete(prompt);
    return JSON.parse(response);
  }

  async executeStep(step) {
    const tool = this.tools[step.tool];

    if (!tool) {
      throw new Error(`Tool ${step.tool} not found`);
    }

    return await tool.run(JSON.parse(step.input));
  }

  async updatePlan(originalPlan, results) {
    const latestResult = results[results.length - 1];

    const prompt = `
Original plan:
${JSON.stringify(originalPlan, null, 2)}

Execution results:
${JSON.stringify(results, null, 2)}

The last step needs adjustment. Update the remaining steps.

Response format:
{
  "steps": [...updated steps]
}
`;

    const response = await this.llm.complete(prompt);
    return JSON.parse(response);
  }
}
```

## 多 Agent 协作

### 协作框架

```javascript
class AgentOrchestrator {
  constructor() {
    this.agents = new Map();
    this.messageQueue = [];
  }

  registerAgent(name, agent) {
    this.agents.set(name, agent);
  }

  async sendMessage(fromAgent, toAgent, message) {
    const agent = this.agents.get(toAgent);

    if (!agent) {
      throw new Error(`Agent ${toAgent} not found`);
    }

    const response = await agent.receive(fromAgent, message);
    return response;
  }

  async broadcast(fromAgent, message) {
    const promises = [];

    for (const [name, agent] of this.agents) {
      if (name !== fromAgent) {
        promises.push(agent.receive(fromAgent, message));
      }
    }

    return Promise.all(promises);
  }
}

class BaseAgent {
  constructor(name, llm) {
    this.name = name;
    this.llm = llm;
    this.memory = [];
  }

  async receive(from, message) {
    this.memory.push({ from, message, timestamp: Date.now() });
    return await this.process(message);
  }

  async process(message) {
    throw new Error('Subclass must implement process method');
  }
}
```

### 专门化 Agent

```javascript
// Research Agent - 搜索和收集信息
class ResearchAgent extends BaseAgent {
  constructor(llm, searchTool) {
    super('Researcher', llm);
    this.searchTool = searchTool;
  }

  async process(message) {
    const prompt = `
You are a research agent. Given the following message, determine what to search for.

Message: ${message}

Respond with a JSON object:
{
  "searchQuery": "query to search",
  "numResults": 5
}
`;

    const response = await this.llm.complete(prompt);
    const { searchQuery, numResults } = JSON.parse(response);

    const results = await this.searchTool.run({
      query: searchQuery,
      numResults
    });

    return {
      type: 'research_results',
      data: results
    };
  }
}

// Writer Agent - 生成内容
class WriterAgent extends BaseAgent {
  constructor(llm) {
    super('Writer', llm);
  }

  async process(message) {
    if (message.type !== 'research_results') {
      throw new Error('Expected research results');
    }

    const prompt = `
You are a writer agent. Based on the following research results, write a comprehensive article.

Research results:
${JSON.stringify(message.data, null, 2)}

Write an article that:
1. Summarizes the key findings
2. Provides insights and analysis
3. Is well-structured and engaging
`;

    const article = await this.llm.complete(prompt);

    return {
      type: 'article',
      content: article
    };
  }
}

// Reviewer Agent - 审查和改进
class ReviewerAgent extends BaseAgent {
  constructor(llm) {
    super('Reviewer', llm);
  }

  async process(message) {
    if (message.type !== 'article') {
      throw new Error('Expected article');
    }

    const prompt = `
You are a reviewer agent. Review the following article for:
1. Accuracy and clarity
2. Grammar and style
3. Structure and flow

Article:
${message.content}

Provide feedback and suggest improvements.
`;

    const feedback = await this.llm.complete(prompt);

    return {
      type: 'review',
      feedback
    };
  }
}
