## 任务规划和分解

### 层次任务规划

```javascript
class HierarchicalPlanner {
  constructor(llm) {
    this.llm = llm;
  }

  async plan(goal) {
    // 1. 创建高层计划
    const highLevelPlan = await this.createHighLevelPlan(goal);
    console.log('High-level plan:', highLevelPlan);

    // 2. 分解每个子目标
    const detailedPlan = {
      goal,
      subtasks: []
    };

    for (const subgoal of highLevelPlan.subgoals) {
      const subtaskPlan = await this.createSubtaskPlan(subgoal);
      detailedPlan.subtasks.push(subtaskPlan);
    }

    return detailedPlan;
  }

  async createHighLevelPlan(goal) {
    const prompt = `
Goal: ${goal}

Break down this goal into 3-5 major subgoals.

Format as JSON:
{
  "subgoals": [
    {
      "id": 1,
      "description": "Subgoal description",
      "dependencies": []
    }
  ]
}
`;

    const response = await this.llm.complete(prompt);
    return JSON.parse(response);
  }

  async createSubtaskPlan(subgoal) {
    const prompt = `
Subgoal: ${subgoal.description}

Break down this subgoal into detailed steps.

Format as JSON:
{
  "subgoal": "${subgoal.description}",
  "steps": [
    {
      "step": 1,
      "action": "action description",
      "expected_output": "expected output"
    }
  ]
}
`;

    const response = await this.llm.complete(prompt);
    return JSON.parse(response);
  }
}
```

### 动态任务调整

```javascript
class AdaptivePlanner {
  constructor(llm, tools) {
    this.llm = llm;
    this.tools = tools;
    this.plan = null;
    this.executedSteps = [];
  }

  async run(goal) {
    this.plan = await this.createPlan(goal);

    while (this.plan.remainingSteps.length > 0) {
      const step = this.plan.remainingSteps[0];

      try {
        const result = await this.executeStep(step);
        this.executedSteps.push({ step, result, status: 'success' });

        // 检查是否需要调整计划
        const needsAdjustment = await this.evaluateProgress();

        if (needsAdjustment) {
          await this.adjustPlan();
        }
      } catch (error) {
        console.error('Step failed:', error);
        this.executedSteps.push({ step, error, status: 'failed' });

        // 尝试恢复
        const recovery = await this.recover(step, error);

        if (!recovery) {
          throw new Error(`Failed to execute step: ${step.action}`);
        }
      }

      // 移除已执行的步骤
      this.plan.remainingSteps.shift();
    }

    return this.executedSteps;
  }

  async evaluateProgress() {
    const prompt = `
Current plan:
${JSON.stringify(this.plan, null, 2)}

Executed steps:
${JSON.stringify(this.executedSteps, null, 2)}

Evaluate if the remaining plan is still optimal or needs adjustment.

Respond with JSON:
{
  "needsAdjustment": true/false,
  "reason": "explanation"
}
`;

    const response = await this.llm.complete(prompt);
    return JSON.parse(response);
  }

  async adjustPlan() {
    const prompt = `
Current plan:
${JSON.stringify(this.plan, null, 2)}

Execution history:
${JSON.stringify(this.executedSteps, null, 2)}

Adjust the remaining steps based on the current progress.

Respond with JSON:
{
  "adjustedSteps": [...]
}
`;

    const response = await this.llm.complete(prompt);
    const { adjustedSteps } = JSON.parse(response);

    this.plan.remainingSteps = adjustedSteps;
  }

  async recover(step, error) {
    const prompt = `
Step that failed:
${JSON.stringify(step, null, 2)}

Error: ${error.message}

Suggest a recovery strategy or alternative approach.

Respond with JSON:
{
  "canRecover": true/false,
  "strategy": "recovery strategy",
  "alternativeStep": {...}
}
`;

    const response = await this.llm.complete(prompt);
    const recovery = JSON.parse(response);

    if (!recovery.canRecover) {
      return false;
    }

    if (recovery.alternativeStep) {
      this.plan.remainingSteps[0] = recovery.alternativeStep;
    }

    return true;
  }
}
```

## 记忆和上下文管理

### 短期记忆

```javascript
class ShortTermMemory {
  constructor(maxSize = 100) {
    this.messages = [];
    this.maxSize = maxSize;
  }

  addMessage(role, content) {
    this.messages.push({
      role,
      content,
      timestamp: Date.now()
    });

    // 保持窗口大小
    if (this.messages.length > this.maxSize) {
      this.messages = this.messages.slice(-this.maxSize);
    }
  }

  getRecentMessages(count = 10) {
    return this.messages.slice(-count);
  }

  formatForLLM() {
    return this.messages
      .map(msg => `${msg.role}: ${msg.content}`)
      .join('\n');
  }

  clear() {
    this.messages = [];
  }
}
```

### 长期记忆

```javascript
class LongTermMemory {
  constructor(embeddingModel, vectorStore) {
    this.embeddingModel = embeddingModel;
    this.vectorStore = vectorStore;
  }

  async store(content, metadata = {}) {
    const embedding = await this.embeddingModel.embed(content);

    await this.vectorStore.add({
      content,
      embedding,
      metadata: {
        ...metadata,
        timestamp: Date.now()
      }
    });
  }

  async search(query, topK = 5) {
    const queryEmbedding = await this.embeddingModel.embed(query);

    const results = await this.vectorStore.search({
      vector: queryEmbedding,
      topK
    });

    return results.map(result => ({
      content: result.content,
      score: result.score,
      metadata: result.metadata
    }));
  }

  async summarizeRecent(sessionId, timeWindow = 3600000) {
    const cutoff = Date.now() - timeWindow;

    const recentMemories = await this.vectorStore.search({
      filter: {
        sessionId,
        timestamp: { $gte: cutoff }
      }
    });

    const contents = recentMemories.map(m => m.content).join('\n');

    const summaryPrompt = `
Summarize the following conversation:

${contents}

Provide a concise summary.
`;

    const summary = await this.llm.complete(summaryPrompt);

    return summary;
  }
}
```

### 上下文窗口管理

```javascript
class ContextWindowManager {
  constructor(maxTokens = 4000) {
    this.maxTokens = maxTokens;
    this.messages = [];
    this.tokenEstimator = (text) => text.length / 4; // 粗略估算
  }

  addMessage(role, content) {
    const tokens = this.tokenEstimator(content);

    this.messages.push({
      role,
      content,
      tokens
    });

    this.pruneIfNeeded();
  }

  pruneIfNeeded() {
    const totalTokens = this.messages.reduce(
      (sum, msg) => sum + msg.tokens,
      0
    );

    if (totalTokens > this.maxTokens) {
      // 保留系统消息和最近的消息
      const systemMessages = this.messages.filter(
        msg => msg.role === 'system'
      );

      const conversationMessages = this.messages
        .filter(msg => msg.role !== 'system')
        .slice(-10); // 保留最近 10 条

      this.messages = [...systemMessages, ...conversationMessages];
    }
  }

  formatForLLM() {
    return this.messages.map(msg => ({
      role: msg.role,
      content: msg.content
    }));
  }
}
```

## 实战案例：自动化研究助手

```javascript
// 完整的自动化研究助手系统
class ResearchAssistant {
  constructor(claude, gpt4, searchTool) {
    this.planner = new HierarchicalPlanner(claude);
    this.researchAgent = new ResearchAgent(claude, searchTool);
    this.writerAgent = new WriterAgent(gpt4);
    this.reviewerAgent = new ReviewerAgent(claude);
    this.memory = new LongTermMemory(embeddingModel, vectorStore);
  }

  async research(topic) {
    console.log(`Starting research on: ${topic}`);

    // 1. 创建研究计划
    const plan = await this.planner.plan(topic);
    console.log('Research plan:', plan);

    const results = {
      topic,
      plan,
      findings: [],
      article: null
    };

    // 2. 执行研究计划
    for (const subtask of plan.subtasks) {
      console.log(`Researching: ${subtask.subgoal}`);

      for (const step of subtask.steps) {
        const searchResults = await this.researchAgent.process({
          query: step.action
        });

        results.findings.push({
          subgoal: subtask.subgoal,
          step: step.action,
          data: searchResults
        });

        // 存储到长期记忆
        await this.memory.store(
          JSON.stringify(searchResults),
          { topic, subgoal: subtask.subgoal }
        );
      }
    }

    // 3. 生成文章
    console.log('Writing article...');
    const article = await this.writerAgent.process({
      type: 'research_results',
      data: results
    });

    results.article = article.content;

    // 4. 审查文章
    console.log('Reviewing article...');
    const review = await this.reviewerAgent.process(article);

    // 5. 最终修订
    console.log('Finalizing article...');
    const finalPrompt = `
Original article:
${article.content}

Reviewer feedback:
${review.feedback}

Revise the article based on the feedback.
`;

    const finalArticle = await gpt4.complete(finalPrompt);
    results.finalArticle = finalArticle;

    // 6. 存储最终结果
    await this.memory.store(finalArticle, {
      type: 'final_article',
      topic
    });

    return results;
  }
}

// 使用示例
async function main() {
  const claude = new Anthropic();
  const gpt4 = new OpenAI();
  const searchTool = new BraveSearch();

  const assistant = new ResearchAssistant(claude, gpt4, searchTool);

  const results = await assistant.research(
    'The future of renewable energy in Europe'
  );

  console.log('Final article:', results.finalArticle);
}
```

## 常见问题 (FAQ)

### Q: Agent 陷入死循环怎么办？

A: 防护措施：
1. 设置最大迭代次数
2. 检测重复状态
3. 添加超时机制
4. 实现人工干预接口

### Q: 如何优化 Agent 成本？

A: 成本优化：
1. 使用更小的模型处理简单任务
2. 缓存常见查询结果
3. 批量处理请求
4. 减少上下文窗口大小

### Q: 多 Agent 如何同步状态？

A: 状态同步：
1. 共享记忆系统
2. 消息传递机制
3. 事件总线
4. 共享数据库

