### 作用域和闭包

```javascript
// 块级作用域
{
    let blockScoped = "visible in block";
    console.log(blockScoped);  // 可见
}
// console.log(blockScoped);  // 错误：不可见

// 函数作用域
function outer() {
    let outerVar = "outer";

    function inner() {
        let innerVar = "inner";
        console.log(outerVar);  // 可以访问外部变量
    }

    inner();
    // console.log(innerVar);  // 错误：不可见
}

// 闭包
function createCounter() {
    let count = 0;
    return {
        increment: () => ++count,
        decrement: () => --count,
        getCount: () => count
    };
}

const counter = createCounter();
console.log(counter.increment());  // 1
console.log(counter.increment());  // 2
console.log(counter.getCount());  // 2
```

