### 4. 断路器

防止级联故障：

~~~javascript
// 断路器模式示例
class CircuitBreaker {
  constructor(threshold = 5) {
    this.failureCount = 0;
    this.threshold = threshold;
    this.state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
    this.lastFailureTime = null;
    this.retryTimeout = 60000; // 1 minute
  }

  async execute(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime > this.retryTimeout) {
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit breaker is OPEN');
      }
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  onSuccess() {
    this.failureCount = 0;
    if (this.state === 'HALF_OPEN') {
      this.state = 'CLOSED';
    }
  }

  onFailure() {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.threshold) {
      this.state = 'OPEN';
    }
  }
}

// 使用断路器
const cb = new CircuitBreaker();
await cb.execute(() => fetch('http://external-service/api'));
~~~

## 数据管理

### 分布式事务

#### Saga 模式

~~~javascript
// 订单 Saga 示例
class OrderSaga {
  async execute(orderData) {
    const transactionId = uuid();

    try {
      // 步骤 1: 创建订单
      const order = await this.createOrder(orderData);

      // 步骤 2: 扣减库存
      await this.reserveInventory(order.items);

      // 步骤 3: 处理支付
      await this.processPayment(order);

      // 步骤 4: 确认订单
      await this.confirmOrder(order.id);

      return order;
    } catch (error) {
      // 补偿事务
      await this.compensate(transactionId);
      throw error;
    }
  }

  async compensate(transactionId) {
    // 回滚操作
    await this.cancelOrder(transactionId);
    await this.releaseInventory(transactionId);
    await this.refundPayment(transactionId);
  }
}
~~~

