### 10. 不足的日志记录和监控

```javascript
// 安全日志记录
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' })
  ]
});

// 记录安全事件
function logSecurityEvent(event) {
  logger.log({
    level: 'warn',
    timestamp: new Date().toISOString(),
    event: event.type,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    userId: req.user?.id,
    details: event.details
  });
}

// 示例：记录失败的登录尝试
if (!loginSuccessful) {
  logSecurityEvent({
    type: 'AUTH_FAILURE',
    details: { username: req.body.username }
  });
}
```

## 实战案例

### 案例 1: 构建安全的登录系统

```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

const app = express();

// 安全中间件
app.use(helmet());
app.use(express.json());

// 登录速率限制
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 15 分钟内最多 5 次尝试
  message: '登录尝试过多，请稍后再试'
});

// 安全登录
app.post('/api/login', loginLimiter, async (req, res) => {
  const { username, password } = req.body;

  // 验证输入
  if (!username || !password) {
    return res.status(400).json({ error: '用户名和密码必填' });
  }

  // 查找用户
  const user = await db.users.findOne({ username });
  if (!user) {
    // 记录失败尝试
    return res.status(401).json({ error: '用户名或密码错误' });
  }

  // 验证密码
  const isValid = await bcrypt.compare(password, user.passwordHash);
  if (!isValid) {
    return res.status(401).json({ error: '用户名或密码错误' });
  }

  // 创建会话
  req.session.userId = user.id;

  res.json({ message: '登录成功' });
});
```

### 案例 2: 防止 CSRF 攻击

```javascript
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
const csrfProtection = csrf({ cookie: true });

// 生成 CSRF token
app.get('/api/form', csrfProtection, (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// 验证 CSRF token
app.post('/api/submit', csrfProtection, (req, res) => {
  // 如果 token 无效，会抛出错误
  res.json({ success: true });
});
```

### 案例 3: 文件上传安全

```javascript
const multer = require('multer');
const path = require('path');

// 安全的文件上传配置
const storage = multer.diskStorage({
  destination: './uploads/',
  filename: (req, file, cb) => {
    // 生成安全的文件名
    const uniqueName = Date.now() + '-' + Math.random().toString(36).substr(2, 9);
    const ext = path.extname(file.originalname);
    cb(null, uniqueName + ext);
  }
});

const upload = multer({
  storage,
  limits: { fileSize: 5 * 1024 * 1024 }, // 5MB
  fileFilter: (req, file, cb) => {
    // 白名单文件类型
    const allowedTypes = ['.jpg', '.jpeg', '.png', '.gif', '.pdf'];
    const ext = path.extname(file.originalname).toLowerCase();

    if (!allowedTypes.includes(ext)) {
      return cb(new Error('不支持的文件类型'));
    }

    // 检查 MIME 类型
    if (!file.mimetype.startsWith('image/') && file.mimetype !== 'application/pdf') {
      return cb(new Error('无效的文件类型'));
    }

    cb(null, true);
  }
});

app.post('/api/upload', upload.single('file'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: '请选择文件' });
  }
  res.json({ filename: req.file.filename });
});
```

