## 常见问题调试

### 1. TypeError: Cannot read property

```javascript
// 问题
const user = null;
console.log(user.name); // TypeError

// 调试
console.log('user:', user);
console.log('type:', typeof user);

// 解决
const name = user?.name || 'Unknown';
```

### 2. Promise Rejection

```javascript
// 问题
fetch('/api/data')
  .then(res => res.json())
  .then(data => processData(data)); // 未捕获错误

// 调试
process.on('unhandledRejection', (err) => {
  console.error('Unhandled rejection:', err);
});

// 解决
fetch('/api/data')
  .then(res => res.json())
  .then(data => processData(data))
  .catch(err => console.error(err));
```

### 3. 异步时序问题

```javascript
// 问题
let value;
async function init() {
  value = await fetchData();
}
init();
console.log(value); // undefined

// 调试
async function init() {
  console.log('before:', value);
  value = await fetchData();
  console.log('after:', value);
}

// 解决
await init();
console.log(value);
```

### 4. 内存泄漏

```javascript
// 检测泄漏
let iterations = 0;
setInterval(() => {
  const used = process.memoryUsage().heapUsed;
  console.log(`Memory: ${Math.round(used / 1024 / 1024)}MB`);
  iterations++;
  if (iterations > 10) process.exit(0);
}, 1000);
```

