// React 错误边界
class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, info) {
    console.error('Error:', error);
    console.error('Info:', info);
  }

  render() {
    if (this.state.hasError) {
      return <h1>Something went wrong.</h1>;
    }
    return this.props.children;
  }
}
```

## 实战案例

### 案例 1: 调试慢 API

```javascript
// 问题：API 响应慢（5秒）

// 1. 添加日志
console.time('api-start');

const user = await db.query('SELECT * FROM users WHERE id = ?', [userId]);
console.timeLog('api-start', 'user fetched');

const orders = await db.query('SELECT * FROM orders WHERE userId = ?', [userId]);
console.timeLog('api-start', 'orders fetched');

const result = processUserOrders(user, orders);
console.timeEnd('api-start');

// 输出：
// api-start: 3200ms user fetched
// api-start: 4800ms orders fetched
// api-start: 5000ms

// 结论：数据库查询慢

// 2. 检查查询计划
EXPLAIN SELECT * FROM orders WHERE userId = 123;

// 结果：Seq Scan（全表扫描）

// 解决：添加索引
CREATE INDEX idx_orders_userId ON orders(userId);
```

