### 无限滚动

```typescript
import { FixedSizeList } from 'react-window';
import InfiniteLoader from 'react-window-infinite-loader';

function InfiniteList({ hasNextPage, loadMoreItems, items }: InfiniteListProps) {
  const isItemLoaded = (index: number) => !!items[index];

  return (
    <InfiniteLoader
      isItemLoaded={isItemLoaded}
      itemCount={hasNextPage ? items.length + 1 : items.length}
      loadMoreItems={loadMoreItems}
    >
      {({ onItemsRendered, ref }) => (
        <FixedSizeList
          ref={ref}
          height={600}
          itemCount={items.length}
          itemSize={50}
          onItemsRendered={onItemsRendered}
          width="100%"
        >
          {({ index, style }) => (
            <div style={style}>
              {items[index]?.name || 'Loading...'}
            </div>
          )}
        </FixedSizeList>
      )}
    </InfiniteLoader>
  );
}
```

### 列表渲染优化

```typescript
// ❌ 避免：使用 index 作为 key（列表会重排时）
function List({ items }: { items: Item[] }) {
  return (
    <ul>
      {items.map((item, index) => (
        <li key={index}>{item.name}</li> // 不稳定的 key
      ))}
    </ul>
  );
}

// ✅ 正确：使用稳定的唯一标识
function List({ items }: { items: Item[] }) {
  return (
    <ul>
      {items.map(item => (
        <li key={item.id}>{item.name}</li> // 稳定的 key
      ))}
    </ul>
  );
}

// ✅ 复杂项使用 memo
const ListItem = memo(function ListItem({ item }: { item: Item }) {
  return (
    <li>
      <span>{item.name}</span>
      <button onClick={() => onToggle(item.id)}>Toggle</button>
    </li>
  );
});
```

## 状态管理优化

### Context 优化

```typescript
// ❌ 问题：任何状态变化都会导致所有消费者重新渲染
const AppContext = createContext<AppContextType | null>(null);

function AppProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState(null);
  const [theme, setTheme] = useState('light');
  const [notifications, setNotifications] = useState([]);

  return (
    <AppContext.Provider value={{ user, setUser, theme, setTheme, notifications, setNotifications }}>
      {children}
    </AppContext.Provider>
  );
}

// ✅ 解决：拆分 Context
const UserContext = createContext<UserContextType | null>(null);
const ThemeContext = createContext<ThemeContextType | null>(null);
const NotificationContext = createContext<NotificationContextType | null>(null);

function AppProviders({ children }: { children: ReactNode }) {
  return (
    <UserProvider>
      <ThemeProvider>
        <NotificationProvider>
          {children}
        </NotificationProvider>
      </ThemeProvider>
    </UserProvider>
  );
}

// 组件只订阅需要的 Context
function ThemeButton() {
  const { theme, setTheme } = useContext(ThemeContext);
  // 只有主题变化时才重新渲染
  return <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>
    Toggle Theme
  </button>;
}
```

### 状态派生

```typescript
// ❌ 冗余状态
function UserProfile() {
  const [user, setUser] = useState(null);
  const [displayName, setDisplayName] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    if (user) {
      setDisplayName(user.name);
      setIsAdmin(user.role === 'admin');
    }
  }, [user]);

  return <div>{displayName} {isAdmin && '(Admin)'}</div>;
}

// ✅ 派生状态
function UserProfile() {
  const [user, setUser] = useState(null);

  const displayName = user?.name || '';
  const isAdmin = user?.role === 'admin';

  return <div>{displayName} {isAdmin && '(Admin)'}</div>;
}
```

## 其他优化技术

### 防抖和节流

```typescript
import { useCallback, useState } from 'react';
import { debounce } from 'lodash';

function SearchInput() {
  const [query, setQuery] = useState('');

  // 防抖：延迟执行
  const debouncedSearch = useCallback(
    debounce((q: string) => {
      searchAPI(q);
    }, 500),
    []
  );

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setQuery(value);
    debouncedSearch(value);
  };

  return <input type="text" value={query} onChange={handleChange} />;
}

// 节流：限制执行频率
import { throttle } from 'lodash';

function ScrollComponent() {
  const handleScroll = useCallback(
    throttle(() => {
      console.log('Scroll position:', window.scrollY);
    }, 100),
    []
  );

  useEffect(() => {
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  return <div>{/* 内容 */}</div>;
}
```

