# Vue.js 组件开发实战

Vue.js 3 带来了全新的 Composition API、更好的 TypeScript 支持、更小的包体积和更高的性能。本教程将深入学习 Vue.js 组件开发的核心技术。

## Vue 3 核心特性

### Composition API vs Options API

Vue 3 提供了两种组件编写方式：

```typescript
// Options API (Vue 2 风格)
export default {
  data() {
    return {
      count: 0,
      message: 'Hello'
    };
  },
  computed: {
    doubled() {
      return this.count * 2;
    }
  },
  methods: {
    increment() {
      this.count++;
    }
  },
  mounted() {
    console.log('Component mounted');
  }
}

// Composition API (Vue 3 推荐)
import { ref, computed, onMounted } from 'vue';

export default {
  setup() {
    const count = ref(0);
    const message = ref('Hello');

    const doubled = computed(() => count.value * 2);

    const increment = () => {
      count.value++;
    };

    onMounted(() => {
      console.log('Component mounted');
    });

    return {
      count,
      message,
      doubled,
      increment
    };
  }
}

// `<script setup>` 语法糖（最简洁）
<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';

const count = ref(0);
const message = ref('Hello');

const doubled = computed(() => count.value * 2);

const increment = () => {
  count.value++;
};

onMounted(() => {
  console.log('Component mounted');
});
</script>
```

## 响应式系统

### ref vs reactive

```typescript
import { ref, reactive } from 'vue';

// ref: 用于基本类型，需要 .value 访问
const count = ref(0);
console.log(count.value); // 0
count.value++;

// reactive: 用于对象，直接访问
const state = reactive({
  count: 0,
  message: 'Hello'
});
console.log(state.count); // 0
state.count++;

// ref 解包（在模板中自动）
<template>
  <div>{{ count }}</div> <!-- 不需要 .value -->
  <button @click="count++">Increment</button>
</template>

// reactive 的限制
const state = reactive({ count: 0 });
let count = state.count; // 失去响应性
count++; // 不会触发更新

// 解决：使用 toRefs
import { toRefs } from 'vue';

function useFeature() {
  const state = reactive({
    count: 0,
    message: 'Hello'
  });

  return toRefs(state); // 保持响应性
}

const { count, message } = useFeature();
count.value++; // 保持响应性
```

### computed 计算属性

```typescript
import { ref, computed } from 'vue';

const firstName = ref('John');
const lastName = ref('Doe');

// 只读计算属性
const fullName = computed(() => `${firstName.value} ${lastName.value}`);

// 可写计算属性
const fullName = computed({
  get() {
    return `${firstName.value} ${lastName.value}`;
  },
  set(value) {
    [firstName.value, lastName.value] = value.split(' ');
  }
});

fullName.value = 'Jane Smith';
console.log(firstName.value); // Jane
console.log(lastName.value); // Smith
```

### watch 和 watchEffect

```typescript
import { ref, watch, watchEffect } from 'vue';

const count = ref(0);
const message = ref('Hello');

// watch: 明确指定依赖
watch(count, (newValue, oldValue) => {
  console.log(`count changed from ${oldValue} to ${newValue}`);
});

// 监听多个源
watch([count, message], ([newCount, newMessage], [oldCount, oldMessage]) => {
  console.log('count or message changed');
});

// 深度监听对象
const state = reactive({ user: { name: 'John' } });
watch(
  () => state.user,
  (newValue) => {
    console.log('user changed:', newValue);
  },
  { deep: true } // 深度监听
);

// watchEffect: 自动追踪依赖
watchEffect(() => {
  console.log(`Count is ${count.value} and message is ${message.value}`);
});

// watchPostEffect: DOM 更新后执行
watchPostEffect(() => {
  console.log('DOM updated');
});

// watchSyncEffect: 同步执行
watchSyncEffect(() => {
  console.log('Sync effect');
});

// 立即执行
watch(count, (val) => {
  console.log(val);
}, { immediate: true });

// 一次性监听
watch(count, (val) => {
  console.log(val);
}, { once: true });
```

## 组件通信

### Props 和 Emits

```typescript
// 父组件
<script setup lang="ts">
import ChildComponent from './ChildComponent.vue';

const message = ref('Hello from parent');
const count = ref(0);

const handleChildEvent = (data: string) => {
  console.log('Received from child:', data);
};
